"""End-to-end run: load data generated by the Go `datagen` tool, fit three
forecasting models on a held-out 90-day test window, score them, plot
actual-vs-predicted, and run a training-window-length ablation.

Run from the `analysis/` directory: `python run_analysis.py`
"""
import json
import time
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd

from forecast_lib import (
    holt_winters_forecast,
    load_series,
    ml_forecast,
    naive_forecast,
    score,
    seasonal_naive_forecast,
    train_test_split,
)

ROOT = Path(__file__).resolve().parent.parent
DATA_CSV = ROOT / "data" / "demand.csv"
PLOTS_DIR = ROOT / "plots"
RESULTS_DIR = ROOT / "analysis" / "results"
TEST_DAYS = 90

RESULTS_DIR.mkdir(exist_ok=True)
PLOTS_DIR.mkdir(exist_ok=True)


def run_main_comparison(df: pd.DataFrame) -> dict:
    train, test = train_test_split(df, TEST_DAYS)
    actual = test["demand"].to_numpy()

    predictions = {}
    timings = {}

    t0 = time.perf_counter()
    predictions["Naive"] = naive_forecast(train, TEST_DAYS)
    timings["Naive"] = time.perf_counter() - t0

    t0 = time.perf_counter()
    predictions["Seasonal Naive (7d)"] = seasonal_naive_forecast(train, TEST_DAYS, season=7)
    timings["Seasonal Naive (7d)"] = time.perf_counter() - t0

    t0 = time.perf_counter()
    predictions["Holt-Winters"] = holt_winters_forecast(train, TEST_DAYS)
    timings["Holt-Winters"] = time.perf_counter() - t0

    t0 = time.perf_counter()
    predictions["GradientBoosting (lag+cal)"] = ml_forecast(train, test)
    timings["GradientBoosting (lag+cal)"] = time.perf_counter() - t0

    rows = []
    for name, pred in predictions.items():
        metrics = score(actual, pred)
        metrics["model"] = name
        metrics["fit_seconds"] = round(timings[name], 3)
        rows.append(metrics)

    results_df = pd.DataFrame(rows)[["model", "MAE", "RMSE", "MAPE", "fit_seconds"]]
    results_df = results_df.sort_values("RMSE").reset_index(drop=True)

    plot_actual_vs_predicted(test, predictions)
    return {"results_df": results_df, "train": train, "test": test, "predictions": predictions}


def plot_actual_vs_predicted(test: pd.DataFrame, predictions: dict) -> None:
    fig, ax = plt.subplots(figsize=(11, 5))
    ax.plot(test["date"], test["demand"], label="Actual", color="black", linewidth=1.8)
    styles = {
        "Naive": dict(linestyle=":", color="#999999"),
        "Seasonal Naive (7d)": dict(linestyle="--", color="#1f77b4"),
        "Holt-Winters": dict(linestyle="-.", color="#ff7f0e"),
        "GradientBoosting (lag+cal)": dict(linestyle="-", color="#2ca02c"),
    }
    for name, pred in predictions.items():
        ax.plot(test["date"], pred, label=name, linewidth=1.3, **styles.get(name, {}))
    ax.set_title(f"Actual vs. forecast demand — held-out {len(test)}-day test window")
    ax.set_xlabel("Date")
    ax.set_ylabel("Daily demand (units)")
    ax.legend(loc="upper left", fontsize=9)
    fig.autofmt_xdate()
    fig.tight_layout()
    out_path = PLOTS_DIR / "actual_vs_predicted.png"
    fig.savefig(out_path, dpi=140)
    plt.close(fig)
    print(f"Saved plot: {out_path}")


def run_window_ablation(df: pd.DataFrame) -> pd.DataFrame:
    """How test-set RMSE/MAE changes as the Holt-Winters and GBM models get
    less training history (holding the 90-day test window fixed)."""
    full_train, test = train_test_split(df, TEST_DAYS)
    actual = test["demand"].to_numpy()
    window_lengths = [120, 240, 365, 545, 730, len(full_train)]

    rows = []
    for w in window_lengths:
        if w > len(full_train):
            continue
        sub_train = full_train.iloc[-w:].reset_index(drop=True)
        hw_pred = holt_winters_forecast(sub_train, TEST_DAYS)
        hw_metrics = score(actual, hw_pred)

        # GBM needs enough history to build lag/rolling features.
        if w < 60:
            continue
        gbm_pred = ml_forecast(sub_train, test)
        gbm_metrics = score(actual, gbm_pred)

        rows.append(
            {
                "train_window_days": w,
                "HW_MAE": round(hw_metrics["MAE"], 2),
                "HW_RMSE": round(hw_metrics["RMSE"], 2),
                "GBM_MAE": round(gbm_metrics["MAE"], 2),
                "GBM_RMSE": round(gbm_metrics["RMSE"], 2),
            }
        )
    return pd.DataFrame(rows)


def main():
    df = load_series(str(DATA_CSV))
    print(f"Loaded {len(df)} rows from {DATA_CSV} ({df['date'].min().date()} to {df['date'].max().date()})")

    comparison = run_main_comparison(df)
    results_df = comparison["results_df"]
    print("\n=== Model comparison on held-out 90-day test window ===")
    print(results_df.to_string(index=False))
    results_df.to_csv(RESULTS_DIR / "model_comparison.csv", index=False)

    print("\nRunning training-window-length ablation...")
    ablation_df = run_window_ablation(df)
    print("\n=== Ablation: test RMSE/MAE vs. training window length ===")
    print(ablation_df.to_string(index=False))
    ablation_df.to_csv(RESULTS_DIR / "window_ablation.csv", index=False)

    summary = {
        "n_rows": len(df),
        "date_min": str(df["date"].min().date()),
        "date_max": str(df["date"].max().date()),
        "test_days": TEST_DAYS,
        "best_model_by_rmse": results_df.iloc[0]["model"],
    }
    with open(RESULTS_DIR / "summary.json", "w") as f:
        json.dump(summary, f, indent=2)
    print("\nDone. Results written to", RESULTS_DIR)


if __name__ == "__main__":
    main()
